// FreeLang Runner - 모바일에서 FreeLang 코드 실행
// 기본 UI: 코드 입력 → 실행 버튼 → 출력 표시

import 'package:flutter/material.dart';
import 'engine_bridge.dart';
import 'execution_log.dart';

void main() {
  runApp(const FreeLangRunnerApp());
}

class FreeLangRunnerApp extends StatelessWidget {
  const FreeLangRunnerApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'FreeLang Runner',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
        useMaterial3: true,
      ),
      home: const RunnerScreen(),
    );
  }
}

class RunnerScreen extends StatefulWidget {
  const RunnerScreen({Key? key}) : super(key: key);

  @override
  State<RunnerScreen> createState() => _RunnerScreenState();
}

class _RunnerScreenState extends State<RunnerScreen> {
  late TextEditingController _codeController;
  late TextEditingController _outputController;

  String? _executionStatus;
  String? _executionError;
  bool _isExecuting = false;
  int? _executionTime;

  @override
  void initState() {
    super.initState();
    _codeController = TextEditingController(
      text: '''// Hello FreeLang!
print "Hello, Mobile!"
''',
    );
    _outputController = TextEditingController();
  }

  @override
  void dispose() {
    _codeController.dispose();
    _outputController.dispose();
    super.dispose();
  }

  Future<void> _runCode() async {
    setState(() {
      _isExecuting = true;
      _executionStatus = '실행 중...';
      _outputController.text = '';
    });

    try {
      final result = await FlEngineBridge.run(
        _codeController.text,
        timeoutMs: 5000,
        mode: RunMode.bytecode,
      );

      setState(() {
        _outputController.text = result.output;
        _executionStatus = result.success
            ? '✓ 완료'
            : '✗ 오류 (코드: ${result.exitCode})';
        _executionError = result.error;
        _executionTime = result.timeMs;
      });
    } catch (e) {
      setState(() {
        _executionError = e.toString();
        _executionStatus = '✗ 오류';
      });
    } finally {
      setState(() {
        _isExecuting = false;
      });
    }
  }

  void _loadExample(String name, String code) {
    _codeController.text = code;
    _outputController.text = '';
    _executionStatus = null;
    _executionError = null;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('FreeLang Runner'),
        elevation: 0,
      ),
      body: Column(
        children: [
          // 상단: 코드 입력
          Expanded(
            flex: 2,
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    'FreeLang 코드',
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Expanded(
                    child: Container(
                      decoration: BoxDecoration(
                        color: Colors.grey[100],
                        border: Border.all(color: Colors.grey[300]!),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: TextField(
                        controller: _codeController,
                        decoration: const InputDecoration(
                          border: InputBorder.none,
                          contentPadding: EdgeInsets.all(12),
                          hintText: 'FreeLang 코드를 입력하세요...',
                        ),
                        maxLines: null,
                        expands: true,
                        font: const TextStyle(
                          fontFamily: 'Monaco',
                          fontSize: 13,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),

          // 실행 버튼 & 상태
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                // 상태 표시
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    if (_executionStatus != null)
                      Text(
                        _executionStatus!,
                        style: TextStyle(
                          fontSize: 12,
                          color: _executionStatus!.contains('✓')
                              ? Colors.green
                              : Colors.red,
                        ),
                      ),
                    if (_executionTime != null)
                      Text(
                        '실행 시간: ${_executionTime}ms',
                        style: const TextStyle(
                          fontSize: 11,
                          color: Colors.grey,
                        ),
                      ),
                  ],
                ),

                // 실행 버튼
                ElevatedButton.icon(
                  onPressed: _isExecuting ? null : _runCode,
                  icon: const Icon(Icons.play_arrow),
                  label: _isExecuting ? const Text('실행 중...') : const Text('실행'),
                ),
              ],
            ),
          ),

          const SizedBox(height: 12),

          // 중간: 출력
          Expanded(
            flex: 1,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    '출력',
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Expanded(
                    child: Container(
                      decoration: BoxDecoration(
                        color: Colors.grey[900],
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: SingleChildScrollView(
                        child: TextField(
                          controller: _outputController,
                          readOnly: true,
                          decoration: const InputDecoration(
                            border: InputBorder.none,
                            contentPadding: EdgeInsets.all(12),
                          ),
                          style: const TextStyle(
                            color: Colors.lightGreen,
                            fontFamily: 'Monaco',
                            fontSize: 12,
                          ),
                          maxLines: null,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),

          // 오류 메시지 (있으면)
          if (_executionError != null && _executionError!.isNotEmpty)
            Container(
              padding: const EdgeInsets.all(12),
              color: Colors.red[100],
              child: Row(
                children: [
                  Icon(Icons.error, color: Colors.red[900]),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      _executionError!,
                      style: TextStyle(
                        color: Colors.red[900],
                        fontSize: 12,
                      ),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ],
              ),
            ),

          const SizedBox(height: 12),
        ],
      ),
      drawer: Drawer(
        child: ListView(
          padding: EdgeInsets.zero,
          children: [
            DrawerHeader(
              decoration: BoxDecoration(
                color: Colors.blue[700],
              ),
              child: const Text(
                'FreeLang Runner',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 24,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
            const ListTile(
              title: Text('예제'),
            ),
            ListTile(
              title: const Text('피보나치'),
              onTap: () => _loadExample(
                'fibonacci',
                '''// 재귀적 피보나치
let fibonacci(n) {
  if n <= 1 { n } else {
    fibonacci(n-1) + fibonacci(n-2)
  }
}
print fibonacci(10)
''',
              ),
            ),
            ListTile(
              title: const Text('배열 정렬'),
              onTap: () => _loadExample(
                'sort',
                '''// 간단한 정렬 예제
let arr = [3, 1, 4, 1, 5, 9]
print arr
''',
              ),
            ),
            ListTile(
              title: const Text('Hello World'),
              onTap: () => _loadExample(
                'hello',
                'print "Hello, FreeLang Mobile!"',
              ),
            ),
          ],
        ),
      ),
    );
  }
}

