class FreeLangRunnerApp extends StatelessWidget {
  const FreeLangRunnerApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'FreeLang Runner',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
        useMaterial3: true,
      ),
      home: const RunnerScreen(),
    );
  }
}

class RunnerScreen extends StatefulWidget {
  const RunnerScreen({Key? key}) : super(key: key);

  @override
  State<RunnerScreen> createState() => _RunnerScreenState();
}

class _RunnerScreenState extends State<RunnerScreen> {
  late TextEditingController _codeController;
  late TextEditingController _outputController;

  String? _executionStatus;
  String? _executionError;
  bool _isExecuting = false;
  int? _executionTime;

  @override
  void initState() {
    super.initState();
    _codeController = TextEditingController(
      text: '''// Hello FreeLang!
print "Hello, Mobile!"
''',
    );
    _outputController = TextEditingController();

    // 엔진 초기화
    _initializeEngine();
  }

  Future<void> _initializeEngine() async {
    try {
      final initialized = await FlEngineBridge.initialize();
      if (!initialized) {
        _showError('엔진 초기화 실패');
      }
    } catch (e) {
      _showError('초기화 오류: $e');
    }
  }

  void _showError(String message) {
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(message)),
      );
    }
  }

  @override
  void dispose() {
    _codeController.dispose();
    _outputController.dispose();
    FlEngineBridge.shutdown();
    super.dispose();
  }

  Future<void> _runCode() async {
    setState(() {
      _isExecuting = true;
      _executionStatus = '실행 중...';
      _outputController.text = '';
    });

    try {
      final result = await FlEngineBridge.run(
        _codeController.text,
        timeoutMs: 5000,
        mode: RunMode.bytecode,
      );

      setState(() {
        _outputController.text = result.output;
        _executionStatus = result.success
            ? '✓ 완료'
            : '✗ 오류 (코드: ${result.exitCode})';
        _executionError = result.error;
        _executionTime = result.timeMs;
      });
    } catch (e) {
      setState(() {
        _executionError = e.toString();
        _executionStatus = '✗ 오류';
      });
    } finally {
      setState(() {
        _isExecuting = false;
      });
    }
  }

  void _loadExample(String name, String code) {
    _codeController.text = code;
    _outputController.text = '';
    _executionStatus = null;
    _executionError = null;
  }

