// feed_screen.dart - 코드 스니펫 피드

import 'package:flutter/material.dart';

class Snippet {
  final String id;
  final String title;
  final String code;
  final String author;
  final List<String> tags;
  final int likes;
  final String createdAt;

  Snippet({
    required this.id,
    required this.title,
    required this.code,
    required this.author,
    required this.tags,
    required this.likes,
    required this.createdAt,
  });
}

class FeedScreen extends StatefulWidget {
  const FeedScreen({Key? key}) : super(key: key);

  @override
  State<FeedScreen> createState() => _FeedScreenState();
}

class _FeedScreenState extends State<FeedScreen> {
  // 샘플 데이터 (실제로는 REST API에서 가져옴)
  final snippets = [
    Snippet(
      id: '1',
      title: '피보나치 수열',
      code: 'let fib(n) { if n <= 1 { n } else { fib(n-1) + fib(n-2) } }',
      author: 'alice',
      tags: ['algorithm', 'recursion'],
      likes: 42,
      createdAt: '2 시간 전',
    ),
    Snippet(
      id: '2',
      title: '배열 정렬',
      code: 'let sort(arr) { /* bubble sort */ }',
      author: 'bob',
      tags: ['sorting', 'array'],
      likes: 28,
      createdAt: '5 시간 전',
    ),
    Snippet(
      id: '3',
      title: '문자열 역순',
      code: 'let reverse(s) { s.chars().reverse().join() }',
      author: 'charlie',
      tags: ['string', 'utility'],
      likes: 15,
      createdAt: '1 일 전',
    ),
  ];

  String? _selectedTag;

  @override
  Widget build(BuildContext context) {
    final filtered = snippets
        .where((s) => _selectedTag == null || s.tags.contains(_selectedTag))
        .toList();

    return CustomScrollView(
      slivers: [
        // 태그 필터
        SliverToBoxAdapter(
          child: SizedBox(
            height: 50,
            child: ListView(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 12),
              children: [
                FilterChip(
                  label: const Text('모두'),
                  selected: _selectedTag == null,
                  onSelected: (_) => setState(() => _selectedTag = null),
                ),
                const SizedBox(width: 8),
                ...['algorithm', 'game', 'utility', 'string', 'array']
                    .map((tag) => Padding(
                          padding: const EdgeInsets.only(right: 8),
                          child: FilterChip(
                            label: Text(tag),
                            selected: _selectedTag == tag,
                            onSelected: (_) =>
                                setState(() => _selectedTag = tag),
                          ),
                        ))
                    .toList(),
              ],
            ),
          ),
        ),

        // 스니펫 목록
        SliverList(
          delegate: SliverChildBuilderDelegate(
            (context, index) {
              final snippet = filtered[index];
              return SnippetCard(snippet: snippet);
            },
            childCount: filtered.length,
          ),
        ),
      ],
    );
  }
}

class SnippetCard extends StatefulWidget {
  final Snippet snippet;

  const SnippetCard({
    Key? key,
    required this.snippet,
  }) : super(key: key);

  @override
  State<SnippetCard> createState() => _SnippetCardState();
}

class _SnippetCardState extends State<SnippetCard> {
  late int _likes;
  late bool _isLiked;

  @override
  void initState() {
    super.initState();
    _likes = widget.snippet.likes;
    _isLiked = false;
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
      child: InkWell(
        onTap: () {
          // 스니펫 상세 보기
        },
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // 제목
              Text(
                widget.snippet.title,
                style: const TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 8),

              // 코드 미리보기
              Container(
                padding: const EdgeInsets.all(8),
                color: Colors.grey[900],
                child: Text(
                  widget.snippet.code,
                  style: TextStyle(
                    fontFamily: 'Monaco',
                    fontSize: 11,
                    color: Colors.grey[300],
                  ),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(height: 8),

              // 태그
              Wrap(
                spacing: 4,
                children: widget.snippet.tags
                    .map((tag) => Chip(
                          label: Text(
                            tag,
                            style: const TextStyle(fontSize: 11),
                          ),
                          visualDensity: VisualDensity.compact,
                        ))
                    .toList(),
              ),
              const SizedBox(height: 8),

              // 작성자, 날짜, 좋아요
              Row(
                children: [
                  CircleAvatar(
                    radius: 16,
                    backgroundColor: Colors.teal[300],
                    child: Text(
                      widget.snippet.author[0].toUpperCase(),
                      style: const TextStyle(
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        widget.snippet.author,
                        style: const TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      Text(
                        widget.snippet.createdAt,
                        style: TextStyle(
                          fontSize: 10,
                          color: Colors.grey[600],
                        ),
                      ),
                    ],
                  ),
                  const Spacer(),
                  IconButton(
                    icon: Icon(
                      _isLiked ? Icons.favorite : Icons.favorite_border,
                      color: _isLiked ? Colors.red : null,
                    ),
                    onPressed: () {
                      setState(() {
                        _isLiked = !_isLiked;
                        _likes += _isLiked ? 1 : -1;
                      });
                    },
                  ),
                  Text('$_likes'),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

