class _LeaderboardScreenState extends State<LeaderboardScreen> {
  final entries = [
    LeaderboardEntry(
      rank: 1,
      username: 'alice_dev',
      score: 2850,
      contributions: 45,
    ),
    LeaderboardEntry(
      rank: 2,
