// tutorials_screen.dart - 단계별 학습 튜토리얼 (REST API 연동)

import 'package:flutter/material.dart';
import '../services/hub_api_client.dart';

class TutorialsScreen extends StatefulWidget {
  const TutorialsScreen({Key? key}) : super(key: key);

  @override
  State<TutorialsScreen> createState() => _TutorialsScreenState();
}

class _TutorialsScreenState extends State<TutorialsScreen> {
  final HubApiClient _apiClient = HubApiClient();

  List<TutorialResponse> _tutorials = [];
  bool _isLoading = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _loadTutorials();
  }

  Future<void> _loadTutorials() async {
    setState(() {
      _isLoading = true;
      _error = null;
    });

    try {
      await _apiClient.initialize();
      final tutorials = await _apiClient.getTutorials();
      setState(() {
        _tutorials = tutorials;
      });
    } catch (e) {
      setState(() {
        _error = e.toString();
        _tutorials = _getLocalTutorials();
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  // 로컬 샘플 데이터
  List<TutorialResponse> _getLocalTutorials() {
    return [
      TutorialResponse(
        id: 1,
        title: 'Hello World 시작하기',
        description: 'FreeLang의 첫 번째 프로그램을 작성해보세요',
        totalSteps: 3,
        difficulty: 1,
        steps: ['프로젝트 생성', 'Hello World 작성', '실행'],
      ),
      TutorialResponse(
        id: 2,
        title: '변수와 타입 이해하기',
        description: 'FreeLang의 타입 시스템 학습',
        totalSteps: 5,
        difficulty: 2,
        steps: ['변수 선언', '기본 타입', '배열', '레코드', '타입 추론'],
      ),
      TutorialResponse(
        id: 3,
        title: '함수 마스터하기',
        description: '함수 정의, 호출, 고차 함수',
        totalSteps: 7,
        difficulty: 3,
        steps: [
          '함수 정의',
          '매개변수',
          '반환값',
          '클로저',
          '고차함수',
          '재귀',
          '패턴매칭'
        ],
      ),
      TutorialResponse(
        id: 4,
        title: '재귀 알고리즘',
        description: '피보나치부터 분할 정복까지',
        totalSteps: 6,
        difficulty: 3,
        steps: ['재귀란', '피보나치', '백트래킹', '분할정복', '동적계획법', '최적화'],
      ),
    ];
  }

  void _showTutorialDetail(TutorialResponse tutorial) {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(tutorial.title),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              tutorial.description,
              style: const TextStyle(fontSize: 14),
            ),
            const SizedBox(height: 16),
            Text(
              '${tutorial.totalSteps}개 단계 | 난이도: ${'⭐' * tutorial.difficulty}',
              style: TextStyle(
                fontSize: 12,
                color: Colors.grey[600],
              ),
            ),
            const SizedBox(height: 12),
            Text(
              '학습 내용:',
              style: const TextStyle(
                fontWeight: FontWeight.bold,
                fontSize: 12,
              ),
            ),
            ...tutorial.steps.map((step) => Padding(
                  padding: const EdgeInsets.only(top: 4),
                  child: Text(
                    '• $step',
                    style: const TextStyle(fontSize: 11),
                  ),
                )),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('닫기'),
          ),
          ElevatedButton(
            onPressed: () {
              Navigator.pop(context);
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(content: Text('튜토리얼 시작!')),
              );
            },
            child: const Text('시작'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 에러 메시지
        if (_error != null && !_isLoading)
          Container(
            padding: const EdgeInsets.all(8),
            color: Colors.orange[100],
            child: Row(
              children: [
                Icon(Icons.warning, color: Colors.orange[900], size: 20),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    '로컬 데이터 표시 중',
                    style: TextStyle(fontSize: 12),
                  ),
                ),
              ],
            ),
          ),

        // 로딩 상태
        if (_isLoading)
          const Expanded(
            child: Center(
              child: CircularProgressIndicator(),
            ),
          ),

        // 튜토리얼 목록
        if (!_isLoading)
          Expanded(
            child: ListView.builder(
              itemCount: _tutorials.length,
              itemBuilder: (context, index) {
                final tutorial = _tutorials[index];
                return Card(
                  margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  child: ListTile(
                    title: Text(tutorial.title),
                    subtitle: Text(
                      '${tutorial.totalSteps} 단계 • 난이도: ${'⭐' * tutorial.difficulty}',
                    ),
                    trailing: const Icon(Icons.arrow_forward_ios),
                    onTap: () => _showTutorialDetail(tutorial),
                  ),
                );
              },
            ),
          ),
      ],
    );
  }
}

