            window.flutter_inappwebview.callHandler('save');
          }
        }

        // 탭 키 → 공백 4개
        if (e.key === 'Tab') {
          e.preventDefault();
          const start = this.selectionStart;
          const end = this.selectionEnd;
          this.value = this.value.substring(0, start) + '    ' + this.value.substring(end);
          this.selectionStart = this.selectionEnd = start + 4;
          this.dispatchEvent(new Event('input'));
        }
      });

      // Dart에서 호출할 메서드들
      window.setEditorContent = function(content) {
        textarea.value = content;
        textarea.dispatchEvent(new Event('input'));
      };

      window.getEditorContent = function() {
        return textarea.value;
      };

      window.insertSnippet = function(snippet) {
        const start = textarea.selectionStart;
        const before = textarea.value.substring(0, start);
        const after = textarea.value.substring(start);
        textarea.value = before + snippet + after;
        textarea.selectionStart = textarea.selectionEnd = start + snippet.length;
        textarea.dispatchEvent(new Event('input'));
      };

      window.getErrors = function() {
        return currentErrors;
      };
    });

    function updateErrorPanel() {
      const panel = document.getElementById('info-panel');
      if (currentErrors.length === 0) {
        panel.innerHTML = '✓ 오류 없음';
        panel.style.color = '#6a9955';
      } else {
        const errorCount = currentErrors.filter(e => e.severity === 'error').length;
        const warningCount = currentErrors.filter(e => e.severity === 'warning').length;
        panel.innerHTML = `
          ${errorCount > 0 ? `<span class="error-line">오류: ${errorCount}</span> ` : ''}
          ${warningCount > 0 ? `<span class="warning-line">경고: ${warningCount}</span>` : ''}
        `;
      }
    }

    // Debounce 유틸리티
    function debounce(fn, delay) {
      let timeoutId = null;
      return function(...args) {
        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => fn.apply(this, args), delay);
      };
    }
  </script>
</body>
</html>
