// editor_screen.dart - CodeMirror 6 + fv-lang-wasm 에디터 (중급)
// 기능: 구문 강조, 실시간 오류 표시, 파일 관리, Runner 연동

import 'package:flutter/material.dart';
import 'package:flutter_inappwebview/flutter_inappwebview.dart';
import '../file_manager.dart';
import '../models/code_file.dart';
import '../editor_html.dart';

class EditorScreen extends StatefulWidget {
  final FileManager fileManager;

  const EditorScreen({
    Key? key,
    required this.fileManager,
  }) : super(key: key);

  @override
  State<EditorScreen> createState() => _EditorScreenState();
}

class _EditorScreenState extends State<EditorScreen> {
  late InAppWebViewController _webController;
  CodeFile? _currentFile;
  bool _isModified = false;
  List<EditorError> _errors = [];
  int _errorCount = 0;
  int _warningCount = 0;

  @override
  void initState() {
    super.initState();
    _currentFile = CodeFile(
      name: 'untitled.fl',
      content: '''// Hello FreeLang!
print "Welcome to FreeLang IDE on Mobile!"
''',
    );
  }

  @override
  void dispose() {
    _webController.clearCache();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          // 파일 정보 + 버튼 바
          Container(
            color: Colors.grey[900],
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(
              children: [
                // 파일명
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Icon(
                            Icons.description,
                            size: 16,
                            color: Colors.grey[500],
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                              _currentFile?.name ?? 'untitled.fl',
                              style: const TextStyle(
                                fontSize: 13,
                                fontWeight: FontWeight.bold,
                              ),
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                          if (_isModified)
                            const Text(
                              ' ●',
                              style: TextStyle(
                                color: Colors.orange,
                                fontSize: 10,
                              ),
                            ),
                        ],
                      ),
                      if (_currentFile?.path != null)
                        Text(
                          _currentFile!.path!,
                          style: TextStyle(
                            fontSize: 11,
                            color: Colors.grey[600],
                          ),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                    ],
                  ),
                ),

                // 버튼 그룹
                PopupMenuButton<String>(
                  onSelected: _handleAction,
                  itemBuilder: (context) => [
                    const PopupMenuItem(
                      value: 'save',
                      child: Text('저장'),
                    ),
                    const PopupMenuItem(
                      value: 'new',
                      child: Text('새 파일'),
                    ),
                    const PopupMenuItem(
                      value: 'open',
                      child: Text('열기'),
                    ),
                  ],
                ),
              ],
            ),
          ),

          // CodeMirror WebView
          Expanded(
            child: InAppWebView(
              initialSettings: InAppWebViewSettings(
                useShouldOverrideUrlLoading: true,
                mediaPlaybackRequiresUserGesture: false,
                javascriptEnabled: true,
              ),
              onWebViewCreated: (controller) {
                _webController = controller;
                _setupMessageHandlers();
                _loadEditorHTML();
              },
              onLoadStop: (controller, url) {
                _initializeEditor();
              },
              onConsoleMessage: (controller, msg) {
                print('[Editor] ${msg.message}');
              },
              onReceivedError: (controller, request, error) {
                print('[Editor Error] $error');
              },
            ),
          ),

          // 상태 바: 오류 정보
          if (_errors.isNotEmpty)
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
              color: Colors.grey[850],
              child: Row(
                children: [
                  if (_errorCount > 0) ...[
                    Icon(Icons.error, size: 14, color: Colors.red),
                    const SizedBox(width: 4),
                    Text(
                      '오류: $_errorCount',
                      style: const TextStyle(color: Colors.red, fontSize: 11),
                    ),
                    const SizedBox(width: 12),
                  ],
                  if (_warningCount > 0) ...[
                    Icon(Icons.warning, size: 14, color: Colors.orange),
                    const SizedBox(width: 4),
                    Text(
                      '경고: $_warningCount',
                      style: const TextStyle(color: Colors.orange, fontSize: 11),
                    ),
                  ],
                  const Spacer(),
                  TextButton(
                    onPressed: _showErrors,
                    child: const Text('세부정보', style: TextStyle(fontSize: 11)),
                  ),
                ],
              ),
            ),

          // 하단: 실행 버튼 + 상태
          Container(
            color: Colors.grey[900],
            padding: const EdgeInsets.all(12),
            child: Row(
              children: [
                ElevatedButton.icon(
                  onPressed: _runCode,
                  icon: const Icon(Icons.play_arrow),
                  label: const Text('실행'),
                ),
                const SizedBox(width: 8),
                ElevatedButton.icon(
                  onPressed: _saveFile,
                  icon: const Icon(Icons.save),
                  label: const Text('저장'),
                ),
                const Spacer(),
                TextButton.icon(
                  onPressed: _runInRunner,
                  icon: const Icon(Icons.arrow_forward),
                  label: const Text('Runner'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  void _loadEditorHTML() {
    // 임시: 간단한 textarea 에디터
    // 실제로는 CodeMirror 6 + fv-lang-wasm.js 임베드
    const html = '''
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { margin: 0; font-family: Monaco, monospace; }
    textarea {
      width: 100%; height: 100%;
      padding: 12px; border: none;
      background: #1e1e1e; color: #d4d4d4;
      font-size: 13px; resize: none;
    }
  </style>
</head>
<body>
  <textarea id="editor"></textarea>
  <script>
    const editor = document.getElementById('editor');

    // Dart와 통신
    window.onload = function() {
      editor.value = "// FreeLang IDE\\nprint \\"Hello\\"";
      editor.focus();
    };

    editor.addEventListener('input', function() {
      window.flutter_inappwebview.callHandler('codeChanged', editor.value);
    });
  </script>
</body>
</html>
''';
    _webController.loadData(data: html);
  }

  void _initializeEditor() {
    if (_currentFile != null) {
      _webController.evaluateJavascript(
        'document.getElementById("editor").value = ${_currentFile!.content.replaceAll('"', '\\"')};',
      );
    }
  }

  void _handleAction(String action) {
    switch (action) {
      case 'save':
        _saveFile();
        break;
      case 'new':
        _newFile();
        break;
      case 'open':
        _openFile();
        break;
    }
  }

  Future<void> _runCode() async {
    // 실행 로직: Runner 앱의 engine_bridge 호출
    // (딥링크로 Runner 열기)
    if (_currentFile != null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('실행: ${_currentFile!.name}'),
          duration: const Duration(seconds: 2),
        ),
      );
    }
  }

  Future<void> _saveFile() async {
    if (_currentFile == null) return;

    try {
      await widget.fileManager.saveFile(
        _currentFile!.name,
        _currentFile!.content,
      );

      setState(() => _isModified = false);

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('저장되었습니다'),
          duration: Duration(seconds: 1),
        ),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('저장 실패: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  void _newFile() {
    setState(() {
      _currentFile = CodeFile(
        name: 'new_file_${DateTime.now().millisecondsSinceEpoch}.fl',
        content: '',
      );
      _isModified = false;
    });
  }

  Future<void> _openFile() async {
    final files = await widget.fileManager.listFiles();

    if (!mounted) return;

    showDialog<FileInfo>(
      context: context,
      builder: (context) => SimpleDialog(
        title: const Text('파일 열기'),
        children: files
            .map((f) => SimpleDialogOption(
                  onPressed: () => Navigator.pop(context, f),
                  child: Text(f.name),
                ))
            .toList(),
      ),
    ).then((file) async {
      if (file != null) {
        final content = await widget.fileManager.readFile(file.path);
        setState(() {
          _currentFile = CodeFile(
            name: file.name,
            content: content,
            path: file.path,
          );
          _isModified = false;
        });
        _initializeEditor();
      }
    });
  }
}

