// ==================== LSP 클라이언트 ====================

class FreeLangLSPClient {
  static final FreeLangLSPClient _instance = FreeLangLSPClient._internal();

  factory FreeLangLSPClient() {
    return _instance;
  }

  FreeLangLSPClient._internal();

  // 내장 FreeLang 키워드 & 내장 함수 (로컬 검증)
  final _keywords = <String>{
    'let', 'fn', 'if', 'else', 'match', 'while', 'for', 'return',
    'break', 'continue', 'true', 'false', 'nil', 'import', 'module',
    'record', 'variant', 'type', 'impl', 'pub', 'mut', 'ref',
  };

  final _builtins = <String>{
    'print', 'println', 'input', 'len', 'push', 'pop', 'reverse',
    'map', 'filter', 'fold', 'range', 'zip', 'unzip', 'assert',
    'abs', 'min', 'max', 'sort', 'join', 'split', 'chars',
    'to_string', 'to_int', 'to_float',
  };

  /// 코드 검증 (진단)
  /// 간단한 구문 검사: 괄호, 따옴표 매칭 등
  Future<List<DiagnosticItem>> validateCode(String code) async {
    return Future.delayed(const Duration(milliseconds: 100), () {
      final diagnostics = <DiagnosticItem>[];
      final lines = code.split('\n');

      for (int lineIdx = 0; lineIdx < lines.length; lineIdx++) {
        final line = lines[lineIdx];

        // 1. 괄호 짝 확인
        int parenCount = 0;
        int bracketCount = 0;
        int braceCount = 0;
        bool inString = false;

        for (int i = 0; i < line.length; i++) {
          final ch = line[i];

          // 문자열 내부는 무시
          if (ch == '"' && (i == 0 || line[i - 1] != '\\')) {
            inString = !inString;
          }

          if (!inString) {
            switch (ch) {
              case '(':
                parenCount++;
                break;
              case ')':
                parenCount--;
                break;
              case '[':
                bracketCount++;
                break;
              case ']':
                bracketCount--;
                break;
              case '{':
                braceCount++;
                break;
              case '}':
                braceCount--;
                break;
            }
          }
        }

        // 괄호 불일치
        if (parenCount < 0) {
          diagnostics.add(DiagnosticItem(
            line: lineIdx,
            startCol: line.lastIndexOf(')'),
            endCol: line.lastIndexOf(')') + 1,
            message: '예상치 않은 닫는 괄호 )',
            severity: 1, // error
          ));
        }
        if (bracketCount < 0) {
          diagnostics.add(DiagnosticItem(
            line: lineIdx,
            startCol: line.lastIndexOf(']'),
            endCol: line.lastIndexOf(']') + 1,
            message: '예상치 않은 닫는 괄호 ]',
            severity: 1,
          ));
        }
        if (braceCount < 0) {
          diagnostics.add(DiagnosticItem(
            line: lineIdx,
            startCol: line.lastIndexOf('}'),
            endCol: line.lastIndexOf('}') + 1,
            message: '예상치 않은 닫는 괄호 }',
            severity: 1,
          ));
        }

        // 따옴표 불일치
        if (inString) {
          diagnostics.add(DiagnosticItem(
            line: lineIdx,
            startCol: 0,
            endCol: line.length,
            message: '닫혀있지 않은 따옴표',
            severity: 1,
          ));
        }

        // 2. 미사용 변수 경고 (간단한 휴리스틱)
        final letMatch = RegExp(r'let\s+(\w+)').allMatches(line);
        for (final match in letMatch) {
          final varName = match.group(1);
          if (varName != null && !_isVariableUsed(code, varName, lineIdx)) {
            diagnostics.add(DiagnosticItem(
              line: lineIdx,
              startCol: match.start,
              endCol: match.end,
              message: '미사용 변수: $varName',
              severity: 2, // warning
            ));
          }
        }
      }

      return diagnostics;
    });
  }

  /// 자동완성 제안
  Future<List<CompletionItem>> getCompletions(
    String code,
    int line,
    int col,
  ) async {
    return Future.delayed(const Duration(milliseconds: 50), () {
      final completions = <CompletionItem>[];
      final lines = code.split('\n');

      if (line >= lines.length) return completions;

      final currentLine = lines[line];
      final prefix = _getWordPrefix(currentLine, col);

      // 키워드 제안
      for (final keyword in _keywords) {
        if (keyword.startsWith(prefix)) {
          completions.add(CompletionItem(
            label: keyword,
            kind: 1, // keyword
            detail: 'FreeLang 키워드',
            insertText: keyword,
          ));
        }
      }

      // 내장함수 제안
      for (final builtin in _builtins) {
        if (builtin.startsWith(prefix)) {
          completions.add(CompletionItem(
            label: builtin,
            kind: 2, // function
            detail: '내장 함수',
            insertText: '$builtin()',
          ));
        }
      }

      // 이전 줄에서 정의된 변수 제안
      final variables = _extractVariables(lines, line);
      for (final varName in variables) {
        if (varName.startsWith(prefix) && varName != prefix) {
          completions.add(CompletionItem(
            label: varName,
            kind: 3, // variable
            detail: '변수',
            insertText: varName,
          ));
        }
      }

      // 정렬 및 중복 제거
      completions.sort((a, b) => a.label.compareTo(b.label));
      return completions
          .fold<List<CompletionItem>>([], (acc, item) {
        if (acc.isEmpty || acc.last.label != item.label) {
          acc.add(item);
        }
        return acc;
      }).take(10).toList();
    });
  }

  /// 호버 정보 (함수/변수 설명)
  Future<HoverInfo?> getHoverInfo(
    String code,
    int line,
    int col,
  ) async {
    return Future.delayed(const Duration(milliseconds: 50), () {
      final lines = code.split('\n');
      if (line >= lines.length) return null;

      final currentLine = lines[line];
      final word = _getWordAtPosition(currentLine, col);

      if (word == null) return null;

      // 키워드 설명
      if (_keywords.contains(word)) {
        return HoverInfo(content: '**$word** - FreeLang 키워드');
      }

      // 내장함수 설명
      if (_builtins.contains(word)) {
        final descriptions = {
          'print': 'print(value) - 값을 출력합니다',
          'len': 'len(arr) - 배열의 길이를 반환합니다',
          'map': 'map(arr, fn) - 배열의 각 요소에 함수를 적용합니다',
          'filter': 'filter(arr, fn) - 조건을 만족하는 요소를 필터링합니다',
          'fold': 'fold(arr, init, fn) - 배열을 축약합니다',
          'range': 'range(start, end) - start부터 end까지의 범위를 생성합니다',
        };
        return HoverInfo(content: descriptions[word] ?? '**$word** - 내장 함수');
      }

      return null;
    });
  }

  // ==================== 헬퍼 메서드 ====================

  String _getWordPrefix(String line, int col) {
    int start = col - 1;
    while (start >= 0 && /[a-zA-Z0-9_]/.hasMatch(line[start])) {
      start--;
    }
    return line.substring(start + 1, col);
  }

  String? _getWordAtPosition(String line, int col) {
    int start = col;
    int end = col;

    while (start > 0 && /[a-zA-Z0-9_]/.hasMatch(line[start - 1])) {
      start--;
    }
    while (end < line.length && /[a-zA-Z0-9_]/.hasMatch(line[end])) {
      end++;
    }

    if (start == end) return null;
    return line.substring(start, end);
  }

  Set<String> _extractVariables(List<String> lines, int upToLine) {
    final variables = <String>{};
    final regex = RegExp(r'let\s+(\w+)');

    for (int i = 0; i < upToLine && i < lines.length; i++) {
      final matches = regex.allMatches(lines[i]);
      for (final match in matches) {
        final varName = match.group(1);
        if (varName != null) {
          variables.add(varName);
        }
      }
    }

    return variables;
  }

  bool _isVariableUsed(String code, String varName, int definitionLine) {
    final lines = code.split('\n');
    final usageRegex = RegExp(r'\b$varName\b');

    int usageCount = 0;
    for (int i = definitionLine; i < lines.length; i++) {
      usageCount += usageRegex.allMatches(lines[i]).length;
    }

    // 정의 자체를 제외 (최소 2번 이상 나타나야 함: 정의 + 사용)
    return usageCount > 1;
  }
}

