// game_parser.dart - FreeLang Game DSL 파서 (중급)
// 문법: scene → sprite → properties, events, actions
//
// 예시:
// scene MainGame {
//   sprite Player { x = 100, y = 200, w = 32, h = 32, speed = 5.0 }
//   on touch(x, y) { move_to(x, y) }
//   on update(dt) { if x > 300 { scene_change("Win") } }
// }

import 'game_ast.dart';

class Token {
  final String type; // identifier, number, string, symbol, keyword
  final String value;
  final int line;
  final int col;

  Token({
    required this.type,
    required this.value,
    required this.line,
    required this.col,
  });

  @override
  String toString() => 'Token($type: "$value" at $line:$col)';
}

class GameDSLParser {
  late List<Token> tokens;
  int _pos = 0;

  // ==================== 토큰화 ====================

  List<Token> tokenize(String code) {
    final tokens = <Token>[];
    int line = 1;
    int col = 1;
    int i = 0;

    while (i < code.length) {
      final ch = code[i];

      // 공백 & 줄바꿈
      if (ch == '\n') {
        line++;
        col = 1;
        i++;
        continue;
      }
      if (ch == ' ' || ch == '\t' || ch == '\r') {
        col++;
        i++;
        continue;
      }

      // 주석
      if (ch == '/' && i + 1 < code.length && code[i + 1] == '/') {
        while (i < code.length && code[i] != '\n') {
          i++;
        }
        continue;
      }

      // 문자열
      if (ch == '"') {
        int start = i;
        i++;
        int strCol = col;
        while (i < code.length && code[i] != '"') {
          if (code[i] == '\n') line++;
          i++;
        }
        if (i < code.length) i++; // 닫는 따옴표

        tokens.add(Token(
          type: 'string',
          value: code.substring(start + 1, i - 1),
          line: line,
          col: strCol,
        ));
        col += i - start;
        continue;
      }

      // 숫자
      if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        int start = i;
        int numCol = col;
        while (i < code.length &&
            ((code[i].codeUnitAt(0) >= 48 && code[i].codeUnitAt(0) <= 57) ||
                code[i] == '.')) {
          i++;
        }
        tokens.add(Token(
          type: 'number',
          value: code.substring(start, i),
          line: line,
          col: numCol,
        ));
        col += i - start;
        continue;
      }

      // 식별자 & 키워드
      if ((ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) || // A-Z
          (ch.codeUnitAt(0) >= 97 && ch.codeUnitAt(0) <= 122) || // a-z
          ch == '_') {
        int start = i;
        int idCol = col;
        while (i < code.length &&
            ((code[i].codeUnitAt(0) >= 65 && code[i].codeUnitAt(0) <= 90) ||
                (code[i].codeUnitAt(0) >= 97 && code[i].codeUnitAt(0) <= 122) ||
                (code[i].codeUnitAt(0) >= 48 && code[i].codeUnitAt(0) <= 57) ||
                code[i] == '_')) {
          i++;
        }

        final word = code.substring(start, i);
        final keywords = {
          'scene', 'sprite', 'on', 'if', 'else', 'while', 'for',
          'move_to', 'rotate', 'show_text', 'scene_change', 'play_sound',
          'true', 'false'
        };

        tokens.add(Token(
          type: keywords.contains(word) ? 'keyword' : 'identifier',
          value: word,
          line: line,
          col: idCol,
        ));
        col += i - start;
        continue;
      }

      // 심볼
      final symbols = ['=', '(', ')', '{', '}', '[', ']', ',', '.', ';'];
      bool found = false;
      for (final sym in symbols) {
        if (code.startsWith(sym, i)) {
          tokens.add(Token(
            type: 'symbol',
            value: sym,
            line: line,
            col: col,
          ));
          i += sym.length;
          col += sym.length;
          found = true;
          break;
        }
      }

      if (!found) {
        i++;
        col++;
      }
    }

    return tokens;
  }

  // ==================== 파싱 ====================

  Game parse(String code) {
    tokens = tokenize(code);
    _pos = 0;

    final scenes = <String, Scene>{};
    String? startSceneId;

    while (!_isAtEnd()) {
      if (_peek().value == 'scene') {
        final scene = _parseScene();
        scenes[scene.id] = scene;
        if (startSceneId == null) startSceneId = scene.id;
      } else {
        _advance();
      }
    }

    return Game(
      id: 'game_${DateTime.now().millisecondsSinceEpoch}',
      title: 'FreeLang Game',
      screenSize: Size(360, 640),
      scenes: scenes,
      startSceneId: startSceneId ?? 'main',
    );
  }

  Scene _parseScene() {
    _consume('keyword', 'scene');
    final sceneId = _consume('identifier', null).value;
    _consume('symbol', '{');

    final sprites = <String, Sprite>{};

    while (_peek().value != '}') {
      if (_peek().value == 'sprite') {
        final sprite = _parseSprite();
        sprites[sprite.id] = sprite;
      } else if (_peek().value == 'on') {
        // 장면 레벨 이벤트 (현재는 무시)
        _advance();
        while (_peek().value != ';' && !_isAtEnd()) {
          _advance();
        }
        if (_peek().value == ';') _advance();
      } else {
        _advance();
      }
    }

    _consume('symbol', '}');

    return Scene(
      id: sceneId,
      title: sceneId,
      sprites: sprites,
      backgroundColor: Color(r: 240, g: 240, b: 240),
    );
  }

  Sprite _parseSprite() {
    _consume('keyword', 'sprite');
    final spriteId = _consume('identifier', null).value;
    _consume('symbol', '{');

    double x = 0, y = 0, w = 32, h = 32;
    double speed = 5.0;
    final eventHandlers = <EventHandler>[];

    while (_peek().value != '}') {
      final key = _peek().value;

      switch (key) {
        case 'x':
          _advance();
          _consume('symbol', '=');
          x = double.tryParse(_consume('number', null).value) ?? 0;
          break;
        case 'y':
          _advance();
          _consume('symbol', '=');
          y = double.tryParse(_consume('number', null).value) ?? 0;
          break;
        case 'w':
          _advance();
          _consume('symbol', '=');
          w = double.tryParse(_consume('number', null).value) ?? 32;
          break;
        case 'h':
          _advance();
          _consume('symbol', '=');
          h = double.tryParse(_consume('number', null).value) ?? 32;
          break;
        case 'speed':
          _advance();
          _consume('symbol', '=');
          speed = double.tryParse(_consume('number', null).value) ?? 5.0;
          break;
        case 'on':
          eventHandlers.add(_parseEventHandler());
          break;
        default:
          _advance();
      }

      if (_peek().value == ',') {
        _advance();
      }
    }

    _consume('symbol', '}');

    return Sprite(
      id: spriteId,
      position: Position(x, y),
      size: Size(w, h),
      speed: speed,
      backgroundColor: Color(r: 100, g: 150, b: 200),
      eventHandlers: eventHandlers,
    );
  }

  EventHandler _parseEventHandler() {
    _consume('keyword', 'on');
    final eventName = _consume('identifier', null).value;
    _consume('symbol', '(');

    // 이벤트 파라미터 (무시)
    while (_peek().value != ')') {
      _advance();
    }
    _consume('symbol', ')');

    _consume('symbol', '{');

    final action = _parseAction();

    _consume('symbol', '}');

    return EventHandler(
      type: _parseEventType(eventName),
      action: action,
    );
  }

  GameAction _parseAction() {
    final actionName = _peek().value;

    switch (actionName) {
      case 'move_to':
        _advance();
        _consume('symbol', '(');
        final x = double.tryParse(_consume('number', null).value) ?? 0;
        _consume('symbol', ',');
        final y = double.tryParse(_consume('number', null).value) ?? 0;
        _consume('symbol', ')');
        return MoveAction(
          spriteId: 'Player',
          target: Position(x, y),
          duration: 500,
        );

      case 'scene_change':
        _advance();
        _consume('symbol', '(');
        final sceneId = _consume('string', null).value;
        _consume('symbol', ')');
        return SceneChangeAction(nextSceneId: sceneId);

      case 'show_text':
        _advance();
        _consume('symbol', '(');
        final text = _consume('string', null).value;
        _consume('symbol', ')');
        return ShowTextAction(
          text: text,
          position: Position(160, 320),
          color: Color(r: 0, g: 0, b: 0),
          fontSize: 24,
        );

      default:
        _advance();
        return ShowTextAction(
          text: 'Action: $actionName',
          position: Position(160, 320),
          color: Color(r: 0, g: 0, b: 0),
          fontSize: 16,
        );
    }
  }

  EventType _parseEventType(String name) {
    switch (name) {
      case 'touch':
        return EventType.touch;
      case 'collision':
        return EventType.collision;
      case 'update':
        return EventType.update;
      case 'timer':
        return EventType.timer;
      default:
        return EventType.custom;
    }
  }

  // ==================== 헬퍼 메서드 ====================

  Token _peek() => _isAtEnd() ? tokens.last : tokens[_pos];

  Token _advance() {
    if (!_isAtEnd()) _pos++;
    return tokens[_pos - 1];
  }

  Token _consume(String type, String? value) {
