// flame_game_runtime.dart - Flame 기반 게임 런타임 (중급)
// 기능: 스프라이트 렌더링, 이벤트 처리, 장면 관리

import 'package:flame/game.dart';
import 'package:flame/events.dart';
import 'package:flame/components.dart';
import '../dsl/game_ast.dart';

// ==================== 게임 런타임 구현 ====================

class FreeLangGameRuntime extends FlameGame with HasCollisionDetection {
  final Game gameDefinition;

  late Scene _currentScene;
  final Map<String, SpriteComponent> _spriteComponents = {};
  final Map<String, Sprite> _sprites = {};
  final List<TextComponent> _textComponents = [];

  bool _isInitialized = false;

  FreeLangGameRuntime({required this.gameDefinition});

  @override
  Color get backgroundColor =>
      Color.fromARGB(255, _currentScene.backgroundColor.r,
          _currentScene.backgroundColor.g, _currentScene.backgroundColor.b);

  @override
  Future<void> onLoad() async {
    await super.onLoad();

    // 시작 장면 로드
    final startScene = gameDefinition.startScene;
    if (startScene != null) {
      await _loadScene(startScene);
      _isInitialized = true;
    }
  }

  Future<void> _loadScene(Scene scene) async {
    // 기존 컴포넌트 제거
    for (final component in _spriteComponents.values) {
      await remove(component);
    }
    _spriteComponents.clear();
    _spriteComponents.removeWhere((key, value) => true);
    _sprites.clear();

    for (final textComponent in _textComponents) {
      await remove(textComponent);
    }
    _textComponents.clear();

    _currentScene = scene;

    // 새 장면 스프라이트 추가
    for (final sprite in scene.spriteList) {
      _sprites[sprite.id] = sprite;

      final component = SpriteComponent(
        position: Vector2(sprite.position.x, sprite.position.y),
        size: Vector2(sprite.size.width, sprite.size.height),
        anchor: Anchor.topLeft,
      );

      // 배경색 그리기
      if (sprite.backgroundColor != null) {
        final bgColor = sprite.backgroundColor!;
        component.paint = Paint()
          ..color = Color.fromARGB(bgColor.a, bgColor.r, bgColor.g, bgColor.b);
      }

      // 충돌 감지 (간단한 사각형)
      component.add(
        RectangleComponent(
          size: Vector2(sprite.size.width, sprite.size.height),
          paint: Paint()..color = const Color.fromARGB(0, 255, 255, 255),
        ),
      );

      await add(component);
      _spriteComponents[sprite.id] = component;
    }
  }

  @override
  void onTapDown(TapDownEvent event) {
    final pos = event.localPosition;

    // 터치된 스프라이트 찾기
    for (final entry in _spriteComponents.entries) {
      final component = entry.value;
      final spriteId = entry.key;
      final sprite = _sprites[spriteId];

      if (sprite != null &&
          pos.x >= component.position.x &&
          pos.x < component.position.x + sprite.size.width &&
          pos.y >= component.position.y &&
          pos.y < component.position.y + sprite.size.height) {
        // 터치 이벤트 처리
        _handleEvent(spriteId, EventType.touch, {'x': pos.x, 'y': pos.y});
      }
    }
  }

  @override
  void update(double dt) {
    super.update(dt);

    if (!_isInitialized) return;

    // 각 스프라이트의 update 이벤트 처리
    for (final spriteId in _sprites.keys) {
      _handleEvent(spriteId, EventType.update, {'dt': dt});
    }
  }

  void _handleEvent(
    String spriteId,
    EventType eventType,
    Map<String, dynamic> params,
  ) {
    final sprite = _sprites[spriteId];
    if (sprite == null) return;

    for (final eventHandler in sprite.eventHandlers) {
      if (eventHandler.type == eventType) {
        // 조건 확인 (간단한 구현)
        bool conditionMet = true;
        if (eventHandler.condition != null) {
          // 조건식 평가 (향후: 더 복잡한 식 평가)
          conditionMet = _evaluateCondition(
            eventHandler.condition!,
            sprite,
            params,
          );
        }

        if (conditionMet) {
          eventHandler.action.execute(this);
        }
      }
    }
  }

  bool _evaluateCondition(
    String condition,
    Sprite sprite,
    Map<String, dynamic> params,
  ) {
    // 간단한 조건식 평가 (완전한 식 파서 아님)
    // 예: "x > 300"
    try {
      if (condition.contains('>')) {
        final parts = condition.split('>');
        final left = parts[0].trim();
        final right = double.tryParse(parts[1].trim()) ?? 0;

        final value = left == 'x'
            ? sprite.position.x
            : left == 'y'
                ? sprite.position.y
                : 0.0;

        return value > right;
      } else if (condition.contains('<')) {
        final parts = condition.split('<');
        final left = parts[0].trim();
        final right = double.tryParse(parts[1].trim()) ?? 0;

        final value = left == 'x'
            ? sprite.position.x
            : left == 'y'
                ? sprite.position.y
                : 0.0;

        return value < right;
      } else if (condition.contains('==')) {
        final parts = condition.split('==');
        final left = parts[0].trim();
        final right = double.tryParse(parts[1].trim()) ?? 0;

        final value = left == 'x'
            ? sprite.position.x
            : left == 'y'
                ? sprite.position.y
                : 0.0;

        return (value - right).abs() < 0.01;
      }
    } catch (e) {
      print('[GameRuntime] 조건 평가 오류: $e');
    }

    return true;
  }

  // ==================== GameRuntime 인터페이스 구현 ====================

  @override
  Sprite? getSprite(String id) => _sprites[id];

  @override
  void animateSprite(String id, Position from, Position to, int duration) {
    final component = _spriteComponents[id];
    if (component == null) return;

    final startPos = component.position;
    final endPos = Vector2(to.x, to.y);
    final distance = startPos.distanceTo(endPos);
    final actualDuration = duration / 1000.0; // 밀리초 → 초

    component.add(
      MoveTo(
        endPos,
        duration: actualDuration,
      ),
    );
  }

  @override
  void showText(String text, Position position, Color color, int fontSize) {
    final textComponent = TextComponent(
      text: text,
      position: Vector2(position.x, position.y),
      anchor: Anchor.topLeft,
      textRenderer: TextPaint(
        style: TextStyle(
          color: flutter.Color.fromARGB(color.a, color.r, color.g, color.b),
          fontSize: fontSize.toDouble(),
          fontFamily: 'Arial',
        ),
      ),
    );

    add(textComponent);
    _textComponents.add(textComponent);

    // 3초 후 사라짐
    Future.delayed(const Duration(seconds: 3), () {
      remove(textComponent);
      _textComponents.remove(textComponent);
    });
  }

  @override
  void changeScene(String sceneId) {
    final nextScene = gameDefinition.getScene(sceneId);
    if (nextScene != null) {
      _loadScene(nextScene);
    }
  }

  @override
  void playSound(String soundId) {
    // TODO: 사운드 재생
    print('[GameRuntime] 사운드: $soundId');
  }
}

// ==================== 헬퍼 클래스 ====================

class MoveTo extends Component {
  final Vector2 target;
  final double duration;
  double elapsed = 0;
  late Vector2 start;

  MoveTo(this.target, {required this.duration});

  @override
  void onMount() {
    start = parent!.position.clone();
  }

  @override
  void update(double dt) {
    elapsed += dt;
    if (elapsed >= duration) {
      parent!.position = target;
      removeFromParent();
      return;
    }

    final progress = elapsed / duration;
    parent!.position = Vector2.lerp(start, target, progress);
  }
}

