class DSLEditorScreen extends StatefulWidget {
  const DSLEditorScreen({Key? key}) : super(key: key);

  @override
  State<DSLEditorScreen> createState() => _DSLEditorScreenState();
}

class _DSLEditorScreenState extends State<DSLEditorScreen> {
  late TextEditingController _controller;
  List<String> _errors = [];
  bool _isValidDSL = true;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(
      text: '''scene MainGame {
  sprite Player {
    x = 160, y = 300,
    w = 32, h = 32,
    on touch(x, y) { move_to(x, y) }
  }
}
''',
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _validateDSL() {
    _errors.clear();
    try {
      final parser = GameDSLParser();
