// deeplink.fl - FreeLang 앱 간 딥링크 프로토콜
// 역할: 앱 간 데이터 교환 및 네비게이션
//
// 스킴:
// - freelang://run?code=BASE64            → Runner 앱 (코드 실행)
// - freelang://edit?snippet_id=X          → IDE 앱 (스니펫 편집)
// - freelang://game?dsl=BASE64            → Game 앱 (게임 플레이)
// - freelang://share?snippet_id=X         → Hub 앱 (스니펫 공유)

record DeepLinkRequest {
  action: String,      // "run", "edit", "game", "share"
  params: String,      // JSON encoded parameters
  timestamp: Int,      // 요청 시간 (밀리초)
}

record RunnerRequest {
  code: String,         // FreeLang 소스 코드 (Base64)
  timeout_ms: Int,      // 실행 타임아웃 (기본 5000)
  mode: String,         // "bytecode" | "native"
}

record IDERequest {
  snippet_id: String,   // 스니펫 ID
  code: String,         // 코드 내용 (선택사항)
  file_name: String,    // 파일명
}

record GameRequest {
  dsl: String,          // Game DSL (Base64)
  title: String,        // 게임 제목
  scene_id: String,     // 시작 장면 (선택사항)
}

record HubRequest {
  snippet_id: String,   // 스니펫 ID
  action: String,       // "view", "share", "comment"
}

// 딥링크 응답 (모든 앱)
record DeepLinkResponse {
  success: Bool,
  message: String,
  result: String,       // JSON encoded result
  error_code: Int,      // 0=success, 1=invalid, 2=not_found
}

// 스니펫 공유 포맷
record ShareableSnippet {
  id: String,
  title: String,
  code: String,
  author: String,
  tags: [String],
  likes: Int,
  created_at: String,
}

