// deeplink_manager.dart - 앱 간 딥링크 관리자 (중급)
// 기능: 딥링크 파싱, 라우팅, 앱 간 통신

import 'dart:convert';
import 'dart:async';
import 'package:uni_links/uni_links.dart';
import 'package:flutter/foundation.dart';

// ==================== 딥링크 데이터 모델 ====================

abstract class DeepLink {
  String get action;
  Map<String, dynamic> get params;
}

class RunnerDeepLink extends DeepLink {
  final String code;
  final int timeoutMs;
  final String mode;

  RunnerDeepLink({
    required this.code,
    required this.timeoutMs,
    required this.mode,
  });

  @override
  String get action => 'run';

  @override
  Map<String, dynamic> get params => {
        'code': code,
        'timeout_ms': timeoutMs,
        'mode': mode,
      };

  factory RunnerDeepLink.fromMap(Map<String, dynamic> map) {
    return RunnerDeepLink(
      code: _decodeBase64(map['code'] as String? ?? ''),
      timeoutMs: map['timeout_ms'] as int? ?? 5000,
      mode: map['mode'] as String? ?? 'bytecode',
    );
  }

  @override
  String toString() =>
      'RunnerDeepLink(code_len=${code.length}, timeout=${timeoutMs}ms)';
}

class IDEDeepLink extends DeepLink {
  final String snippetId;
  final String? code;
  final String fileName;

  IDEDeepLink({
    required this.snippetId,
    this.code,
    required this.fileName,
  });

  @override
  String get action => 'edit';

  @override
  Map<String, dynamic> get params => {
        'snippet_id': snippetId,
        'code': code,
        'file_name': fileName,
      };

  factory IDEDeepLink.fromMap(Map<String, dynamic> map) {
    return IDEDeepLink(
      snippetId: map['snippet_id'] as String? ?? '',
      code: map['code'] as String?,
      fileName: map['file_name'] as String? ?? 'untitled.fl',
    );
  }

  @override
  String toString() => 'IDEDeepLink(snippet_id=$snippetId, file=$fileName)';
}

class GameDeepLink extends DeepLink {
  final String dsl;
  final String title;
  final String? sceneId;

  GameDeepLink({
    required this.dsl,
    required this.title,
    this.sceneId,
  });

  @override
  String get action => 'game';

  @override
  Map<String, dynamic> get params => {
        'dsl': dsl,
        'title': title,
        'scene_id': sceneId,
      };

  factory GameDeepLink.fromMap(Map<String, dynamic> map) {
    return GameDeepLink(
      dsl: _decodeBase64(map['dsl'] as String? ?? ''),
      title: map['title'] as String? ?? 'Game',
      sceneId: map['scene_id'] as String?,
    );
  }

  @override
  String toString() => 'GameDeepLink(title=$title)';
}

class HubDeepLink extends DeepLink {
  final String snippetId;
  final String hubAction;

  HubDeepLink({
    required this.snippetId,
    required this.hubAction,
  });

  @override
  String get action => 'share';

  @override
  Map<String, dynamic> get params => {
        'snippet_id': snippetId,
        'action': hubAction,
      };

  factory HubDeepLink.fromMap(Map<String, dynamic> map) {
    return HubDeepLink(
      snippetId: map['snippet_id'] as String? ?? '',
      hubAction: map['action'] as String? ?? 'view',
    );
  }

  @override
  String toString() => 'HubDeepLink(snippet_id=$snippetId, action=$hubAction)';
}

// ==================== 딥링크 매니저 ====================

class DeepLinkManager {
  static final DeepLinkManager _instance = DeepLinkManager._internal();

  factory DeepLinkManager() {
    return _instance;
  }

  DeepLinkManager._internal();

  final _controller = StreamController<DeepLink>.broadcast();
  StreamSubscription? _deepLinkSubscription;
  bool _initialized = false;

  /// 딥링크 스트림 (구독 가능)
  Stream<DeepLink> get deepLinks => _controller.stream;

  /// 초기화 (앱 시작 시 호출)
  Future<void> initialize() async {
    if (_initialized) return;

    try {
      // 초기 딥링크 확인
      final initialLink = await getInitialLink();
      if (initialLink != null) {
        _handleDeepLink(initialLink);
      }

      // 런타임 딥링크 구독
      _deepLinkSubscription = linkStream.listen(
        _handleDeepLink,
        onError: (err) => print('[DeepLink] Error: $err'),
      );

      _initialized = true;
    } catch (e) {
      print('[DeepLink] 초기화 실패: $e');
    }
  }

  /// 딥링크 생성 (앱 → 앱 호출)
  static String createRunnerLink(String code, {int timeoutMs = 5000}) {
    final encoded = _encodeBase64(code);
    return 'freelang://run?code=$encoded&timeout_ms=$timeoutMs&mode=bytecode';
  }

  static String createIDELink(String snippetId, {String? code, String? fileName}) {
    final codeParam = code != null ? '&code=${_encodeBase64(code)}' : '';
    final fileParam = fileName != null ? '&file_name=$fileName' : '';
    return 'freelang://edit?snippet_id=$snippetId$codeParam$fileParam';
  }

  static String createGameLink(String dsl, {String title = 'Game'}) {
    final encoded = _encodeBase64(dsl);
    return 'freelang://game?dsl=$encoded&title=${Uri.encodeComponent(title)}';
  }

  static String createHubLink(String snippetId, {String action = 'view'}) {
    return 'freelang://share?snippet_id=$snippetId&action=$action';
  }

  void _handleDeepLink(String? link) {
    if (link == null) return;

    try {
      final uri = Uri.parse(link);
      final scheme = uri.scheme;
      final host = uri.host;

      print('[DeepLink] Received: $scheme://$host');

      final deepLink = switch (host) {
        'run' => RunnerDeepLink.fromMap(
            _parseQueryParams(uri.queryParameters)),
        'edit' => IDEDeepLink.fromMap(
            _parseQueryParams(uri.queryParameters)),
        'game' => GameDeepLink.fromMap(
            _parseQueryParams(uri.queryParameters)),
        'share' => HubDeepLink.fromMap(
            _parseQueryParams(uri.queryParameters)),
        _ => null,
      };

      if (deepLink != null) {
        _controller.add(deepLink);
        print('[DeepLink] Parsed: $deepLink');
      }
    } catch (e) {
      print('[DeepLink] 파싱 오류: $e');
    }
  }

  Map<String, dynamic> _parseQueryParams(Map<String, String> params) {
    return Map<String, dynamic>.from(params);
  }

  /// 정리 (앱 종료 시)
  void dispose() {
    _deepLinkSubscription?.cancel();
    _controller.close();
  }

  // ==================== 유틸리티 ====================

  static String _encodeBase64(String text) {
    return base64Encode(utf8.encode(text));
  }

  static String _decodeBase64(String encoded) {
    try {
      return utf8.decode(base64Decode(encoded));
    } catch (e) {
      return encoded; // 디코딩 실패 시 원본 반환
    }
  }
}

