// snippets.go - FreeLang 스니펫 REST API (중급)
// 엔드포인트: /api/v2/snippets (CRUD + 검색 + 좋아요)

package api

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"time"
)

// ==================== 데이터 모델 ====================

type Snippet struct {
	ID        string    `json:"id"`
	Title     string    `json:"title"`
	Code      string    `json:"code"`
	Author    string    `json:"author"`
	Tags      []string  `json:"tags"`
	Likes     int       `json:"likes"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

type CreateSnippetRequest struct {
	Title  string   `json:"title"`
	Code   string   `json:"code"`
	Author string   `json:"author"`
	Tags   []string `json:"tags"`
}

type SnippetResponse struct {
	Success bool        `json:"success"`
	Data    interface{} `json:"data"`
	Error   string      `json:"error,omitempty"`
}

type PaginatedResponse struct {
	Success bool         `json:"success"`
	Data    []Snippet    `json:"data"`
	Total   int          `json:"total"`
	Page    int          `json:"page"`
	Limit   int          `json:"limit"`
	Error   string       `json:"error,omitempty"`
}

// ==================== 데이터베이스 초기화 ====================

func InitSnippetsTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS snippets (
		id TEXT PRIMARY KEY,
		title TEXT NOT NULL,
		code TEXT NOT NULL,
		author TEXT NOT NULL,
		tags TEXT NOT NULL,
		likes INTEGER DEFAULT 0,
		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
		updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
	);

	CREATE INDEX IF NOT EXISTS idx_snippets_author ON snippets(author);
	CREATE INDEX IF NOT EXISTS idx_snippets_created_at ON snippets(created_at DESC);
	`

	_, err := db.Exec(schema)
	return err
}

// ==================== 핸들러 ====================

// GET /api/v2/snippets - 스니펫 목록 (페이징, 필터)
func GetSnippets(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		page := 1
		limit := 10
		tag := ""

		if p := r.URL.Query().Get("page"); p != "" {
			if v, err := strconv.Atoi(p); err == nil && v > 0 {
				page = v
			}
		}
		if l := r.URL.Query().Get("limit"); l != "" {
			if v, err := strconv.Atoi(l); err == nil && v > 0 && v <= 100 {
				limit = v
			}
		}
		if t := r.URL.Query().Get("tag"); t != "" {
			tag = t
		}

		offset := (page - 1) * limit

		// 쿼리 구성
		query := "SELECT id, title, code, author, tags, likes, created_at, updated_at FROM snippets"
		args := []interface{}{}

		if tag != "" {
			query += " WHERE tags LIKE ?"
			args = append(args, "%"+tag+"%")
		}

		query += " ORDER BY created_at DESC LIMIT ? OFFSET ?"
		args = append(args, limit, offset)

		rows, err := db.Query(query, args...)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var snippets []Snippet
		for rows.Next() {
			var s Snippet
			var tags string
			if err := rows.Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt); err != nil {
				continue
			}
			if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
				s.Tags = []string{}
			}
			snippets = append(snippets, s)
		}

		// 총 개수
		countQuery := "SELECT COUNT(*) FROM snippets"
		countArgs := []interface{}{}
		if tag != "" {
			countQuery += " WHERE tags LIKE ?"
			countArgs = append(countArgs, "%"+tag+"%")
		}

		var total int
		db.QueryRow(countQuery, countArgs...).Scan(&total)

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(PaginatedResponse{
			Success: true,
			Data:    snippets,
			Total:   total,
			Page:    page,
			Limit:   limit,
		})
	}
}

// GET /api/v2/snippets/:id - 스니펫 단건 조회
func GetSnippet(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		var s Snippet
		var tags string
		err := db.QueryRow(
			"SELECT id, title, code, author, tags, likes, created_at, updated_at FROM snippets WHERE id = ?",
			id,
		).Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt)

		if err == sql.ErrNoRows {
			http.Error(w, "스니펫을 찾을 수 없습니다", http.StatusNotFound)
			return
		}
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
			s.Tags = []string{}
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(SnippetResponse{
			Success: true,
			Data:    s,
		})
	}
}

// POST /api/v2/snippets - 스니펫 생성
func CreateSnippet(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req CreateSnippetRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid request", http.StatusBadRequest)
			return
		}

		// 유효성 검증
		if req.Title == "" || req.Code == "" || req.Author == "" {
			http.Error(w, "title, code, author는 필수입니다", http.StatusBadRequest)
			return
		}

		// 스니펫 ID 생성
		id := "snippet_" + fmt.Sprintf("%d", time.Now().UnixMilli())
		now := time.Now()

		// 태그 직렬화
		tagsJSON, _ := json.Marshal(req.Tags)

		_, err := db.Exec(
			"INSERT INTO snippets (id, title, code, author, tags, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
			id, req.Title, req.Code, req.Author, string(tagsJSON), now, now,
		)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(SnippetResponse{
			Success: true,
			Data: map[string]interface{}{
				"id":         id,
				"created_at": now,
			},
		})
	}
}

// DELETE /api/v2/snippets/:id - 스니펫 삭제
func DeleteSnippet(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		result, err := db.Exec("DELETE FROM snippets WHERE id = ?", id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		affected, _ := result.RowsAffected()
		if affected == 0 {
			http.Error(w, "스니펫을 찾을 수 없습니다", http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(SnippetResponse{
			Success: true,
			Data: map[string]string{
				"message": "삭제되었습니다",
			},
		})
	}
}

// POST /api/v2/snippets/:id/like - 스니펫 좋아요
func LikeSnippet(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		_, err := db.Exec("UPDATE snippets SET likes = likes + 1 WHERE id = ?", id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		var likes int
		db.QueryRow("SELECT likes FROM snippets WHERE id = ?", id).Scan(&likes)

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(SnippetResponse{
			Success: true,
			Data: map[string]interface{}{
				"likes": likes,
			},
		})
	}
}

// GET /api/v2/snippets/search - 스니펫 검색
func SearchSnippets(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query().Get("q")
		if q == "" {
			http.Error(w, "검색어를 입력하세요", http.StatusBadRequest)
			return
		}

		query := `
		SELECT id, title, code, author, tags, likes, created_at, updated_at
		FROM snippets
		WHERE title LIKE ? OR code LIKE ? OR author LIKE ?
		ORDER BY created_at DESC
		LIMIT 20
		`

		searchTerm := "%" + q + "%"
		rows, err := db.Query(query, searchTerm, searchTerm, searchTerm)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var snippets []Snippet
		for rows.Next() {
			var s Snippet
			var tags string
			if err := rows.Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt); err != nil {
				continue
			}
			if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
				s.Tags = []string{}
			}
			snippets = append(snippets, s)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(SnippetResponse{
			Success: true,
			Data:    snippets,
		})
	}
}

