type Server struct {
	db     *sql.DB
	router *http.ServeMux
	config ServerConfig
}

type ServerConfig struct {
	Port      string
	DBPath    string
	Env       string // "dev" or "prod"
	JWTSecret string
}

type HealthResponse struct {
	Status    string `json:"status"`
	Timestamp int64  `json:"timestamp"`
	Version   string `json:"version"`
}

// ==================== 서버 생성 ====================

func NewServer(config ServerConfig) (*Server, error) {
	// 데이터베이스 초기화
	db, err := sql.Open("sqlite3", config.DBPath)
	if err != nil {
		return nil, err
	}

	if err := db.Ping(); err != nil {
		return nil, err
	}

	// 테이블 생성
	if err := InitSnippetsTable(db); err != nil {
		return nil, err
	}
	if err := InitTutorialsTable(db); err != nil {
		return nil, err
	}
	if err := InitLeaderboardTable(db); err != nil {
		return nil, err
	}

	server := &Server{
		db:     db,
		router: http.NewServeMux(),
		config: config,
	}

	server.setupRoutes()
	return server, nil
}

// ==================== 라우팅 ====================

func (s *Server) setupRoutes() {
	// 헬스체크
	s.router.HandleFunc("GET /health", s.Health)

	// 스니펫 API
	s.router.HandleFunc("GET /api/v2/snippets", s.withCORS(GetSnippets(s.db)))
	s.router.HandleFunc("GET /api/v2/snippets/{id}", s.withCORS(GetSnippet(s.db)))
	s.router.HandleFunc("POST /api/v2/snippets", s.withCORS(CreateSnippet(s.db)))
	s.router.HandleFunc("DELETE /api/v2/snippets/{id}", s.withCORS(DeleteSnippet(s.db)))
	s.router.HandleFunc("POST /api/v2/snippets/{id}/like", s.withCORS(LikeSnippet(s.db)))
	s.router.HandleFunc("GET /api/v2/snippets/search", s.withCORS(SearchSnippets(s.db)))

	// 튜토리얼 API
	s.router.HandleFunc("GET /api/v2/tutorials", s.withCORS(GetTutorials(s.db)))
	s.router.HandleFunc("GET /api/v2/tutorials/{id}", s.withCORS(GetTutorial(s.db)))

	// 리더보드 API
	s.router.HandleFunc("GET /api/v2/leaderboard", s.withCORS(GetLeaderboard(s.db)))

	// 통계 API
	s.router.HandleFunc("GET /api/v2/stats", s.withCORS(s.GetStats))
}

// ==================== 핸들러 ====================

func (s *Server) Health(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(HealthResponse{
		Status:    "healthy",
		Timestamp: time.Now().Unix(),
		Version:   "1.0.0",
	})
}

func (s *Server) GetStats(w http.ResponseWriter, r *http.Request) {
	var snippetCount, totalLikes int

	s.db.QueryRow("SELECT COUNT(*) FROM snippets").Scan(&snippetCount)
	s.db.QueryRow("SELECT SUM(likes) FROM snippets").Scan(&totalLikes)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"success":        true,
		"snippet_count":  snippetCount,
		"total_likes":    totalLikes,
		"timestamp":      time.Now().Unix(),
	})
}

// ==================== 미들웨어 ====================

// CORS 미들웨어
func (s *Server) withCORS(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")

		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}

		next(w, r)
	}
}

// ==================== 서버 실행 ====================

func (s *Server) Start() error {
	log.Printf("[Server] Starting on port %s", s.config.Port)
	return http.ListenAndServe(":"+s.config.Port, s.router)
}

func (s *Server) Close() error {
	return s.db.Close()
}

// ==================== 에러 응답 ====================

type ErrorResponse struct {
	Success bool   `json:"success"`
	Error   string `json:"error"`
	Code    int    `json:"code"`
}

func WriteError(w http.ResponseWriter, statusCode int, message string, code int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(statusCode)
	json.NewEncoder(w).Encode(ErrorResponse{
		Success: false,
		Error:   message,
		Code:    code,
	})
}

