	TotalSteps  int      `json:"total_steps"`
	Difficulty  int      `json:"difficulty"`
	Steps       []string `json:"steps"`
}

func InitTutorialsTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS tutorials (
		id INTEGER PRIMARY KEY,
		title TEXT NOT NULL,
		description TEXT NOT NULL,
		total_steps INTEGER NOT NULL,
		difficulty INTEGER NOT NULL,
		steps TEXT NOT NULL
	);
	`
	_, err := db.Exec(schema)
	return err
}

// GET /api/v2/tutorials
func GetTutorials(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		rows, err := db.Query(
			"SELECT id, title, description, total_steps, difficulty, steps FROM tutorials ORDER BY id",
		)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var tutorials []Tutorial
		for rows.Next() {
			var t Tutorial
			var stepsJSON string
			if err := rows.Scan(&t.ID, &t.Title, &t.Description, &t.TotalSteps, &t.Difficulty, &stepsJSON); err != nil {
				continue
			}
			if err := json.Unmarshal([]byte(stepsJSON), &t.Steps); err != nil {
				t.Steps = []string{}
			}
			tutorials = append(tutorials, t)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    tutorials,
		})
	}
}

// GET /api/v2/tutorials/:id
func GetTutorial(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		var t Tutorial
		var stepsJSON string
		err := db.QueryRow(
			"SELECT id, title, description, total_steps, difficulty, steps FROM tutorials WHERE id = ?",
			id,
		).Scan(&t.ID, &t.Title, &t.Description, &t.TotalSteps, &t.Difficulty, &stepsJSON)

		if err == sql.ErrNoRows {
			http.Error(w, "튜토리얼을 찾을 수 없습니다", http.StatusNotFound)
			return
		}
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		if err := json.Unmarshal([]byte(stepsJSON), &t.Steps); err != nil {
			t.Steps = []string{}
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    t,
		})
	}
}

