// leaderboard.go - 리더보드 API

package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
)

type LeaderboardEntry struct {
	Rank          int    `json:"rank"`
	Username      string `json:"username"`
	Score         int    `json:"score"`
	Contributions int    `json:"contributions"`
}

func InitLeaderboardTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS leaderboard (
		id INTEGER PRIMARY KEY,
		username TEXT NOT NULL,
		score INTEGER DEFAULT 0,
		contributions INTEGER DEFAULT 0,
		period TEXT DEFAULT 'alltime',
		updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
	);

	CREATE UNIQUE INDEX IF NOT EXISTS idx_leaderboard_period ON leaderboard(username, period);
	`
	_, err := db.Exec(schema)
	return err
}

// GET /api/v2/leaderboard
func GetLeaderboard(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		period := r.URL.Query().Get("period")
		if period == "" {
			period = "alltime"
		}

		rows, err := db.Query(`
			SELECT
				ROW_NUMBER() OVER (ORDER BY score DESC) as rank,
				username, score, contributions
			FROM leaderboard
			WHERE period = ?
			LIMIT 50
		`, period)

		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var entries []LeaderboardEntry
		for rows.Next() {
			var e LeaderboardEntry
			if err := rows.Scan(&e.Rank, &e.Username, &e.Score, &e.Contributions); err != nil {
				continue
			}
			entries = append(entries, e)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    entries,
			"period":  period,
		})
	}
}

