// engine_bridge_test.dart - Runner 엔진 브릿지 단위 테스트
// 테스트: 입력 검증, 타임아웃, 오류 처리

import 'package:flutter_test/flutter_test.dart';
import 'package:runner/engine_bridge.dart';

void main() {
  group('FlEngineBridge Unit Tests', () {
    // ==================== 초기화 테스트 ====================
    test('엔진 초기화 실패 처리', () async {
      final result = await FlEngineBridge.initialize();
      expect(result, isA<bool>());
    });

    // ==================== 입력 검증 테스트 ====================
    group('입력 검증', () {
      test('빈 코드 거부', () async {
        final result = await FlEngineBridge.run('');
        expect(result.success, false);
        expect(result.error, contains('비어있습니다'));
      });

      test('타임아웃 범위 검증', () async {
        // 너무 작은 타임아웃
        final result1 = await FlEngineBridge.run(
          'print "test"',
          timeoutMs: 50,
        );
        expect(result1.success, false);
        expect(result1.error, contains('타임아웃'));

        // 너무 큰 타임아웃
        final result2 = await FlEngineBridge.run(
          'print "test"',
          timeoutMs: 400000,
        );
        expect(result2.success, false);
      });

      test('정상 타임아웃 범위', () async {
        final result = await FlEngineBridge.run(
          'print "Hello"',
          timeoutMs: 5000,
        );
        expect(result.exitCode, isNotNull);
      });
    });

    // ==================== 실행 모드 테스트 ====================
    group('실행 모드', () {
      test('바이트코드 모드 지정', () async {
        final result = await FlEngineBridge.run(
          'print "test"',
          mode: RunMode.bytecode,
        );
        expect(result, isA<ExecutionResult>());
      });

      test('네이티브 모드 지정', () async {
        final result = await FlEngineBridge.run(
          'print "test"',
          mode: RunMode.native,
        );
        expect(result, isA<ExecutionResult>());
      });
    });

    // ==================== 오류 처리 테스트 ====================
    group('오류 처리', () {
      test('ExecutionResult 오류 코드', () async {
        final result = await FlEngineBridge.run('');
        expect(result.exitCode, -1); // 입력 검증 오류
      });

      test('오류 메시지 포맷', () async {
        final result = await FlEngineBridge.run('');
        expect(result.error, isNotEmpty);
        expect(result.error, isA<String>());
      });
    });

    // ==================== 토큰화 테스트 ====================
    test('코드 토큰화', () async {
      final tokens = await FlEngineBridge.tokenize('print "hello"');
      expect(tokens, isA<List<Token>>());
      expect(tokens.length, greaterThan(0));
    });

    test('빈 코드 토큰화', () async {
      final tokens = await FlEngineBridge.tokenize('');
      expect(tokens, isEmpty);
    });

    // ==================== 검증 테스트 ====================
    test('코드 검증', () async {
      final errors = await FlEngineBridge.check('print "test"');
      expect(errors, isA<List<LspError>>());
    });

    // ==================== 자동완성 테스트 ====================
    test('자동완성 제안', () async {
      final completions = await FlEngineBridge.complete(
        'let x = 10\nprint ',
        line: 1,
        col: 6,
      );
      expect(completions, isA<List<Completion>>());
    });

    // ==================== 정리 테스트 ====================
    test('엔진 정리', () async {
      await FlEngineBridge.shutdown();
      // 정리 후 재초기화 가능
      final result = await FlEngineBridge.initialize();
      expect(result, isA<bool>());
    });
  });

  // ==================== 실행 결과 모델 테스트 ====================
  group('ExecutionResult Model Tests', () {
    test('fromMap 생성자', () {
      final map = {
        'success': true,
        'output': 'Hello',
        'error': '',
        'time_ms': 150,
        'exit_code': 0,
      };

      final result = ExecutionResult.fromMap(map);
      expect(result.success, true);
      expect(result.output, 'Hello');
      expect(result.timeMs, 150);
    });

    test('toString 포맷', () {
      final result = ExecutionResult(
        success: true,
        output: 'test',
        error: '',
        timeMs: 100,
        exitCode: 0,
      );

      final str = result.toString();
      expect(str, contains('success: true'));
      expect(str, contains('100ms'));
    });
  });

  // ==================== Token 모델 테스트 ====================
  group('Token Model Tests', () {
    test('Token.fromMap', () {
      final map = {
        'type': 0, // keyword
        'start': 10,
        'length': 5,
      };

      final token = Token.fromMap(map);
      expect(token.type, 0);
      expect(token.typeName, 'keyword');
    });

    test('Token.typeName 매핑', () {
      final keywords = [
        Token(type: 0, start: 0, length: 5),
        Token(type: 1, start: 0, length: 5),
        Token(type: 2, start: 0, length: 5),
      ];

      expect(keywords[0].typeName, 'keyword');
      expect(keywords[1].typeName, 'identifier');
      expect(keywords[2].typeName, 'number');
    });
  });

  // ==================== LspError 모델 테스트 ====================
  group('LspError Model Tests', () {
    test('LspError 심각도 플래그', () {
      final error = LspError(
        line: 1,
        col: 5,
        message: 'Test error',
        severity: 1, // error
      );

      expect(error.isError, true);
      expect(error.isWarning, false);
      expect(error.isInfo, false);
    });

    test('LspError.fromMap', () {
      final map = {
        'line': 2,
        'col': 3,
        'message': 'Undefined variable',
        'severity': 1,
      };

      final error = LspError.fromMap(map);
      expect(error.line, 2);
      expect(error.isError, true);
    });
  });

  // ==================== Completion 모델 테스트 ====================
  group('Completion Model Tests', () {
    test('Completion.kindName', () {
      final items = [
        Completion(label: 'let', kind: 1, detail: 'keyword'),
        Completion(label: 'print', kind: 2, detail: 'function'),
        Completion(label: 'x', kind: 3, detail: 'variable'),
      ];

      expect(items[0].kindName, 'keyword');
      expect(items[1].kindName, 'function');
      expect(items[2].kindName, 'variable');
    });
  });
}

